const $=s=>document.querySelector(s);const games=await fetch('games.json').then(r=>r.json());let selected=games[0],brand='philips',running=false,powered=true,crt=true;
const models={philips:{name:'PHILIPS',model:'VG-8235',type:'MSX2',machine:'MSX2E',hz:'PAL / 50 Hz'},sony:{name:'SONY',model:'HB-F700P',type:'MSX2',machine:'MSX2E',hz:'PAL / 50 Hz'},panasonic:{name:'Panasonic',model:'FS-A1WSX',type:'MSX2+',machine:'MSX2PJ',hz:'NTSC / 60 Hz'}};
function render(){const filtered=games.filter(g=>g.title.toLowerCase().includes($('#search').value.toLowerCase()));$('#game-list').replaceChildren(...filtered.map(g=>{const b=document.createElement('button');b.className='game-card'+(selected.id===g.id?' selected':'');b.setAttribute('aria-pressed',String(selected.id===g.id));b.innerHTML=`<img src="${g.image}" alt="Screenshot ${g.title}" loading="lazy"><div><strong>${g.title}</strong><small>MSX BASIC</small></div><span class="number">${selected.id===g.id?'↗':String(g.id+1).padStart(2,'0')}</span>`;b.onclick=()=>{selected=g;$('#selected-title').textContent=g.title;$('#start').innerHTML='Start game <span>↗</span>';render()};return b}));if(!filtered.length)$('#game-list').textContent='Geen games gevonden. Probeer een andere naam.'}
function status(t){$('#status').lastChild.textContent=' '+t}
function start(){powered=true;$('#screen').classList.remove('off-screen');running=true;$('#idle').hidden=true;const f=$('#emulator');f.hidden=false;f.src='emulator/index.html?'+new URLSearchParams({MACHINE:models[brand].machine,DISKA_FILES_URL:'../games/'+selected.file,BASIC_RUN:selected.run,SCREEN_FULLSCREEN_MODE:'2',SCREEN_CONTROL_BAR:'0',SCREEN_CRT_SCANLINES:'0',SCREEN_FILTER_MODE:'0',AUTO_POWER_ON_DELAY:'0'});status('Laden: '+selected.title+'…');$('#start').innerHTML='Opnieuw spelen <span>↗</span>'}
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.source!==$('#emulator').contentWindow)return;if(e.data?.type==='msx-ready')status(selected.title+' · klik in het scherm om te spelen');if(e.data?.type==='msx-error')status('Laden mislukt · probeer Herstart')});$('#start').onclick=start;$('#search').oninput=render;
for(const b of document.querySelectorAll('.brand'))b.onclick=()=>{brand=b.dataset.brand;document.querySelectorAll('.brand').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b))});const m=models[brand];$('.desk').dataset.computer=brand;$('#model-info').textContent=`${m.name.toUpperCase()} ${m.model} · ${m.type}`;$('#monitor-brand').textContent=m.name;$('#computer-brand').textContent=m.name;$('#computer-model').textContent=m.model;$('.scene-meta').lastElementChild.textContent='●  '+m.hz;if(running)start()};
$('#crt').onclick=()=>{crt=!crt;$('#screen').classList.toggle('crt-off',!crt);$('#crt').setAttribute('aria-pressed',String(crt));$('#crt span').textContent=crt?'CRT aan':'CRT uit';$('#emulator').contentWindow.postMessage({type:'msx-crt',value:crt},location.origin)};$('#restart').onclick=start;
$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#screen').requestFullscreen()}catch{status('Volledig scherm wordt niet ondersteund in deze browser')}};
$('#power').onclick=()=>{powered=!powered;$('#screen').classList.toggle('off-screen',!powered);$('#power').setAttribute('aria-pressed',String(powered));if(!powered){$('#emulator').src='about:blank';$('#emulator').hidden=true;$('#idle').hidden=false;running=false;status('Computer uit')}else status('Klaar voor de start')};
const rows=[['F1','F2','F3','F4','F5','ESC','STOP'],['1','2','3','4','5','6','7','8','9','0','−','+','BS'],['TAB','Q','W','E','R','T','Y','U','I','O','P','[',']'],['CTRL','A','S','D','F','G','H','J','K','L',';', '↵'],['SHIFT','Z','X','C','V','B','N','M',',','.','/','SHIFT'],['CAPS','GRAPH','CODE','SPACE','SELECT']];$('#keyboard').innerHTML=rows.map(row=>'<div class="keyrow">'+row.map(k=>`<span class="key ${k==='SPACE'?'space':''} ${k.length>1&&k!=='SPACE'?'alt':''}">${k==='SPACE'?'':k}</span>`).join('')+'</div>').join('');
const dialog=$('#info-dialog');function show(kind){$('#dialog-content').innerHTML=kind==='help'?`<p class="eyebrow">EVEN TERUG NAAR TOEN</p><h2>Klaar? Typ RUN.<br>Of klik gewoon op start.</h2><ol><li>Kies je computer.</li><li>Kies een game en klik op <b>Start game</b>.</li><li>Klik in het beeldscherm om je toetsenbord te activeren. WebMSX kan een extra klik vragen voor geluid.</li><li>Volg de originele spelinstructies. Meestal gebruik je <kbd>↑ ↓ ← →</kbd>, <kbd>Spatie</kbd> en <kbd>Enter</kbd>. De toetsen verschillen per game.</li></ol><p>Het WebMSX-menu biedt ook een virtueel toetsenbord en aanraakbediening. Met <kbd>Esc</kbd> verlaat je volledig scherm.</p>`:`<p class="eyebrow">THE BASIC YEARS / 1992—1994</p><h2>Een toetsenbord.<br>Een hoofd vol ideeën.</h2><p>Tussen 1992 en 1994 maakte Jeroen Derwort deze 27 games in MSX BASIC. Van Airplane tot Fantasieland: de originele programma’s zijn hier weer speelbaar.</p><p>De computers zijn gestileerde illustraties van de Philips VG-8235, Sony HB-F700P en Panasonic FS-A1WSX. WebMSX gebruikt een bijpassend generiek MSX2- of MSX2+-profiel met standaard emulator-BIOS’en; geen modelspecifieke firmware.</p><p>Games en screenshots: <a href="https://www.jeroenderwort.nl/wp-content/uploads/jermsx/jermsx.html" target="_blank" rel="noopener"><u>Jeroens originele collectie ↗</u></a>. Emulatie: <a href="https://github.com/ppeccin/WebMSX" target="_blank" rel="noopener"><u>WebMSX van Paulo Augusto Peccin ↗</u></a>.</p>`;dialog.showModal()};$('#help-open').onclick=()=>show('help');$('#about-open').onclick=()=>show('about');$('#story-link').onclick=()=>show('about');$('.close-dialog').onclick=()=>dialog.close();document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!dialog.open){e.preventDefault();$('#search').focus()}});render();
